import json, time, urllib.request, urllib.error, sys
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = "http://localhost:8080"
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive: 31 May inclusive

log = []
token = None

def raw(method, path, auth=False):
    headers = {}
    if auth:
        headers["Authorization"] = "Bearer " + token
    req = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, r.headers, r.read()
    except urllib.error.HTTPError as e:
        return e.code, e.headers, e.read()

def get_token():
    global token
    st, _, body = raw("POST", "/token")
    token = json.loads(body)["token"]
    log.append(f"token fetched: {token}")

def call(method, path, auth=False):
    attempts = 0
    while True:
        attempts += 1
        if attempts > 60:
            raise RuntimeError(f"giving up on {path} after {attempts} attempts")
        if auth and token is None:
            get_token()
        st, hdrs, body = raw(method, path, auth)
        if st == 200:
            return json.loads(body)
        if st == 404:
            return None
        if st == 401:
            log.append(f"401 on {path}, refreshing token")
            get_token()
            continue
        if st == 429:
            ra = hdrs.get("Retry-After")
            wait = float(ra) if ra else 1.0
            log.append(f"429 on {path}, Retry-After={ra!r}, body={body[:200]!r}")
            time.sleep(wait)
            continue
        if st >= 500:
            log.append(f"{st} on {path}, retrying")
            time.sleep(1.0)
            continue
        raise RuntimeError(f"unexpected {st} on {path}: {body[:200]!r}")

# --- collect orders ---
seen = {}          # order id -> order dict (first listing)
listings = {}      # order id -> count of listings
conflicts = []
page = 1
total_pages = None
while True:
    data = call("GET", f"/orders?page={page}", auth=True)
    if data is None:
        raise RuntimeError(f"orders page {page} returned 404")
    total_pages = data["total_pages"]
    for o in data["items"]:
        oid = o["id"]
        listings[oid] = listings.get(oid, 0) + 1
        if oid in seen:
            if seen[oid] != o:
                conflicts.append(oid)
        else:
            seen[oid] = o
    log.append(f"page {page}/{total_pages}: {len(data['items'])} items, next={data['next']!r}")
    if data["next"] is None or page >= total_pages:
        break
    page += 1

# --- customers ---
cust_cache = {}
def customer(cid):
    if cid not in cust_cache:
        cust_cache[cid] = call("GET", f"/customers/{cid}", auth=True)
    return cust_cache[cid]

# --- filter and total ---
by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
total = 0
count = 0
unknown_customers = []
bad_ts = []
status_counts = {}
for oid, o in seen.items():
    status_counts[o["status"]] = status_counts.get(o["status"], 0) + 1
    try:
        ts = datetime.fromisoformat(o["placed_at"].replace("Z", "+00:00"))
    except Exception:
        bad_ts.append(oid)
        continue
    if ts.tzinfo is None:
        bad_ts.append(oid)
        continue
    ts = ts.astimezone(timezone.utc)
    if not (START <= ts < END):
        continue
    if o["status"] != "shipped":
        continue
    c = customer(o["customer_id"])
    if c is None:
        unknown_customers.append(oid)
        continue
    pct = int(c["discount_pct"])
    amt = Decimal(o["amount_cents"]) * (100 - pct) / 100
    disc = int(amt.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    total += disc
    by_region[c["region"]] += disc
    count += 1

dups = sum(n - 1 for n in listings.values())
result = {
    "total_cents": total,
    "order_count": count,
    "duplicates_skipped": dups,
    "by_region": by_region,
}
print(json.dumps(result, indent=2))
print("distinct orders:", len(seen), "listings:", sum(listings.values()))
print("status counts:", status_counts)
print("conflicting duplicate listings:", conflicts)
print("unparseable/naive timestamps:", bad_ts)
print("unknown customers (excluded):", unknown_customers)
print("customers cached:", len(cust_cache))
print("log events:", len(log))
for line in log:
    if not line.startswith("page "):
        print("  ", line)
json.dump(result, open("/tmp/recon/result_candidate.json", "w"), indent=2)
EOF
cd /tmp/recon && python3 -I reconcile.py

